{
  "name": "agentcanvas",
  "private": true,
  "license": "MIT",
  "scripts": {
    "build": "pnpm --filter @agentcanvas/shared build && pnpm --filter web build && pnpm --filter mcp-gateway build",
    "build:web": "pnpm --filter web build",
    "build:gateway": "pnpm --filter mcp-gateway build",
    "dev:web": "pnpm --filter web dev",
    "dev:gateway": "pnpm --filter mcp-gateway dev",
    "dev:api": "cd apps/api && go run ./cmd/server",
    "dev:full": "concurrently \"pnpm dev:api\" \"pnpm dev:web\"",
    "dev:site": "pnpm --filter tandem-next dev",
    "dev:mock": "VITE_MOCK=1 pnpm --filter web dev",
    "dev": "concurrently \"pnpm dev:web\" \"pnpm dev:gateway\""
  },
  "devDependencies": {
    "concurrently": "^10.0.4"
  }
}

{
  "name": "tandem-next",
  "version": "0.1.0",
  "private": true,
  "description": "tandemcanvas.com — the Tandem marketing site: one static Next.js page, deployed on Vercel from this folder.",
  "scripts": {
    "dev": "next dev",
    "build": "next build",
    "start": "next start",
    "lint": "next lint"
  },
  "dependencies": {
    "next": "^15.5.25",
    "react": "^18.3.1",
    "react-dom": "^18.3.1"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "@types/react": "^18.3.3",
    "@types/react-dom": "^18.3.0",
    "typescript": "^5.4.5"
  }
}
